def _sha(data):return hashlib.sha256(data).hexdigest()
def _git(root,*args):
 p=subprocess.run(['git','-c','credential.helper=','-c','core.hooksPath=/dev/null','-C',str(root),*args],capture_output=True,timeout=30)
 assert p.returncode==0,(args,p.stderr.decode(errors='replace'))
 return p.stdout

def validate(manifest,root):
 root=Path(root).resolve()
 assert manifest['schema']=='apatch.public-source.v4'
 assert manifest['version']=='0.8.51'
 assert manifest['baseline_commit']==BASELINE
 assert manifest['private_git_history_included'] is False
 assert manifest['generated_artifacts_excluded'] is True
 assert manifest['self_excluded']=='PUBLIC-SOURCE-MANIFEST.json'
 historical=manifest['historical_public_source']
 assert historical['public_commit']==BASELINE
 assert historical['manifest_sha256']==HISTORICAL_SHA256
 old=historical['manifest']
 old_bytes=_git(root,'show',BASELINE+':PUBLIC-SOURCE-MANIFEST.json')
 assert _sha(old_bytes)==HISTORICAL_SHA256
 assert json.loads(old_bytes)==old
 _git(root,'merge-base','--is-ancestor',old['contract_intake_source']['source_commit'],BASELINE)
 _git(root,'merge-base','--is-ancestor',BASELINE,'HEAD')
 oldfiles={r['path']:r for r in old['files']}
 files={r['path']:r for r in manifest['files']}
 assert len(files)==len(manifest['files'])
 assert set(files)==set(oldfiles)|EXPECTED_ADDITIONS
 delta={r['path']:r for r in manifest['release_delta']}
 assert len(delta)==len(manifest['release_delta'])
 assert set(delta)==REVIEWED_DELTA_PATHS
 observed={p for p in files if files[p]['sha256']!=oldfiles.get(p,{}).get('sha256')}
 assert observed==REVIEWED_DELTA_PATHS
 runtime={p:r['sha256']for p,r in files.items()if p.startswith(('apatch/','apatch_search_workflows/'))}
 assert runtime==EXPECTED_RUNTIME
 actual_runtime={str(p.relative_to(root))for name in ['apatch','apatch_search_workflows']for p in(root/name).rglob('*')if p.is_file()and'__pycache__'not in p.parts}
 assert actual_runtime==set(runtime)
 assert manifest['runtime_files_total']==len(runtime)
 assert manifest['runtime_files_unchanged']==sum(p in oldfiles and oldfiles[p]['sha256']==digest for p,digest in runtime.items())
 assert set(manifest['runtime_files_added'])==set(runtime)-set(oldfiles)
 assert set(manifest['runtime_files_modified'])=={p for p,digest in runtime.items()if p in oldfiles and oldfiles[p]['sha256']!=digest}
 for p,row in files.items():
  rel=Path(p)
  assert not rel.is_absolute()and'..'not in rel.parts
  assert set(row)=={'path','sha256','bytes','mode','runtime_baseline_unchanged'}
  path=root/rel
  assert path.is_file()and not path.is_symlink()and path.resolve().is_relative_to(root)
  assert path.stat().st_nlink==1
  content=path.read_bytes()
  assert _sha(content)==row['sha256']and len(content)==row['bytes']
  assert row['mode']==('0o755'if path.stat().st_mode&0o111 else'0o644')
  expected_unchanged=p in runtime and oldfiles.get(p,{}).get('sha256')==row['sha256']
  assert row['runtime_baseline_unchanged'] is expected_unchanged
  if p in delta:
   assert delta[p]=={'path':p,'before_sha256':oldfiles.get(p,{}).get('sha256'),'after_sha256':row['sha256']}
  assert not p.startswith(('apatch_pro/','trustchain_pro/','avatar_contract/','.git/','.trustchain/'))
 for name in PRIVATE_MODULES:assert 'apatch/'+name+'.py'not in files
 import tomllib
 assert tomllib.loads((root/'pyproject.toml').read_text())['project']['version']=='0.8.51'
 return True
